import React from 'react';
import { motion } from 'framer-motion';

const QUICK = [
  { t: 'AAPL', p: 214.35, c: +1.24 },
  { t: 'NVDA', p: 132.45, c: +3.21 },
  { t: 'TSLA', p: 185.20, c: -2.15 },
];

const DEFAULT_STOCKS = [
  { ticker: 'AAPL',  name: 'Apple Inc.' },
  { ticker: 'MSFT',  name: 'Microsoft Corporation' },
  { ticker: 'GOOGL', name: 'Alphabet Inc.' },
  { ticker: 'TSLA',  name: 'Tesla Inc.' },
  { ticker: 'AMZN',  name: 'Amazon.com Inc.' },
  { ticker: 'META',  name: 'Meta Platforms Inc.' },
  { ticker: 'NVDA',  name: 'NVIDIA Corporation' },
  { ticker: 'JPM',   name: 'JPMorgan Chase & Co.' },
];

const StockSelector = ({ selectedStock, onStockChange, onPredict, loading, supportedStocks }) => {
  const stocks = supportedStocks?.length ? supportedStocks : DEFAULT_STOCKS;

  return (
    <div className="selector-row">
      {/* Main dropdown */}
      <div className="sel-main-card">
        <div className="sel-lbl">Select Stock</div>
        <div className="sel-wrap">
          <select
            className="stock-select"
            value={selectedStock}
            onChange={e => onStockChange(e.target.value)}
            disabled={loading}
          >
            {stocks.map(s => (
              <option key={s.ticker} value={s.ticker}>
                {s.ticker} — {s.name}
              </option>
            ))}
          </select>
          <span className="sel-arrow">▾</span>
        </div>
      </div>

      {/* Quick-click cards */}
      {QUICK.map(q => (
        <div
          key={q.t}
          className="quick-card"
          onClick={() => !loading && onStockChange(q.t)}
        >
          <div className="qc-sym">{q.t}</div>
          <div className="qc-px">${q.p.toFixed(2)}</div>
          <div className={`qc-chg ${q.c >= 0 ? 'qc-up' : 'qc-dn'}`}>
            {q.c >= 0 ? '▲' : '▼'}{Math.abs(q.c).toFixed(2)}%
          </div>
        </div>
      ))}

      {/* Predict button */}
      <motion.button
        className="predict-button"
        onClick={onPredict}
        disabled={loading}
        whileHover={{ scale: loading ? 1 : 1.04 }}
        whileTap={{ scale: loading ? 1 : 0.96 }}
      >
        {loading ? (
          <><span className="spin-sm" /><span>Analyzing…</span></>
        ) : (
          <><span>⚡</span><span>PREDICT</span></>
        )}
      </motion.button>
    </div>
  );
};

export default StockSelector;
